<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Démo : page partenaire OrthoMaster</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,300;12..96,600;12..96,800&family=Figtree:wght@400;500;600&display=swap" rel="stylesheet">
<style>
  :root{
    --bg:#e3ebf0; --bg2:#cfdde7; --ink:#13293d; --muted:#4d6578; --teal:#1f8379; --teal-ink:#ffffff;
    --line:rgba(19,41,61,.16); --panel:rgba(227,235,240,.8); --card:#f3f7f9;
    --om:#FF9600; --om-ink:#1f1405;
    --display:"Bricolage Grotesque", "Avenir Next", "Segoe UI", system-ui, sans-serif;
    --body:"Figtree", "Helvetica Neue", Arial, system-ui, sans-serif;
    box-sizing:border-box;
    padding-top:env(safe-area-inset-top,0px);
    padding-bottom:env(safe-area-inset-bottom,0px);
  }
  @media (prefers-color-scheme: dark){
    :root:not([data-theme="light"]){
      --bg:#10283a; --bg2:#1a3d57; --ink:#ece7dc; --muted:#9db2c3; --teal:#4cbcb0; --teal-ink:#0d2231;
      --line:rgba(236,231,220,.15); --panel:rgba(16,40,58,.76); --card:#16344b;
    }
  }
  :root[data-theme="dark"]{
    --bg:#10283a; --bg2:#1a3d57; --ink:#ece7dc; --muted:#9db2c3; --teal:#4cbcb0; --teal-ink:#0d2231;
    --line:rgba(236,231,220,.15); --panel:rgba(16,40,58,.76); --card:#16344b;
  }
  *,*::before,*::after{box-sizing:inherit}
  html{scroll-padding-top:env(safe-area-inset-top,0px);scroll-behavior:smooth}
  body{
    margin:0;color:var(--ink);font-family:var(--body);font-size:1.0625rem;line-height:1.6;
    background:var(--bg);
    background-image:radial-gradient(ellipse 60% 70% at 70% 45%, var(--bg2), var(--bg) 70%);
    background-attachment:fixed;-webkit-font-smoothing:antialiased;
    transition:background-color .5s;
  }
  #scene{position:fixed;inset:0;width:100%;height:100%;z-index:0;display:block}
  a{color:inherit}
  :focus-visible{outline:2px solid var(--teal);outline-offset:3px;border-radius:6px}

  main{position:relative;z-index:1}
  .wrap{padding:0 clamp(1.25rem,5vw,4rem);max-width:1280px;margin:0 auto}
  .col{max-width:34rem}

  .hero{min-height:100vh;min-height:100svh;display:flex;flex-direction:column;justify-content:center;padding:4rem 0}
  .avatar{width:clamp(7rem,14vw,9.5rem);aspect-ratio:1;border-radius:50%;margin:0 0 1.8rem;
    background:var(--card);display:grid;place-items:end center;overflow:hidden;
    box-shadow:0 0 0 6px var(--bg),0 0 0 7.5px var(--teal)}
  .avatar svg{width:82%;height:82%;color:var(--muted);opacity:.55}
  .partner{display:inline-flex;align-items:center;gap:.5rem;margin:0 0 1.4rem;font-size:.92rem;color:var(--muted)}
  .partner::before{content:"";width:.55rem;height:.55rem;border-radius:50%;background:var(--om)}
  .partner b{color:var(--ink);font-weight:600}
  h1{font-family:var(--display);font-weight:800;font-size:clamp(3.6rem,11.5vw,9.5rem);line-height:.84;letter-spacing:-.045em;margin:0}
  h1 .dr{display:block;font-weight:300;font-size:.28em;letter-spacing:-.01em;margin-bottom:.35em;color:var(--teal)}
  h1 .ln{display:block}
  .role{font-family:var(--display);font-weight:300;font-size:clamp(1.2rem,2.3vw,1.6rem);margin:1.4rem 0 0;line-height:1.3}
  .creds{letter-spacing:.01em}
  .expertise{list-style:none;margin:1.3rem 0 0;padding:0;display:flex;flex-wrap:wrap;gap:.5rem;max-width:34rem}
  .expertise li{padding:.42rem .9rem;border-radius:999px;font-size:.9rem;font-weight:500;line-height:1.2;
    color:var(--teal);border:1px solid color-mix(in srgb, var(--teal) 45%, transparent);
    background:color-mix(in srgb, var(--teal) 9%, transparent)}
  .hero p.lede{max-width:30rem;margin:1.3rem 0 0;color:var(--muted)}
  .hint{margin-top:3.5rem;font-size:.9rem;color:var(--muted);display:flex;align-items:center;gap:.7rem}
  .hint::before{content:"";width:1px;height:2.4rem;background:var(--teal);transform-origin:top;animation:drip 2.4s ease-in-out infinite}
  @keyframes drip{0%{transform:scaleY(0)}50%{transform:scaleY(1)}100%{transform:scaleY(1);opacity:0}}

  .actions{display:flex;flex-wrap:wrap;gap:.7rem}
  .hero .actions{margin-top:2rem}
  .btn{
    display:inline-flex;align-items:center;gap:.6rem;padding:.8rem 1.25rem;border-radius:999px;
    font:600 .98rem/1 var(--body);text-decoration:none;border:1.5px solid var(--line);
    background:transparent;color:var(--ink);transition:background .2s,border-color .2s,transform .2s;
  }
  .btn svg{width:1.15em;height:1.15em;flex:none}
  .btn .ico{width:1.25em;height:1.25em;flex:none;border-radius:5px;display:block}
  .btn svg.ico{width:1.25em;height:1.25em}
  .btn:hover{border-color:var(--ink);transform:translateY(-1px)}
  .btn.om{background:var(--om);border-color:var(--om);color:var(--om-ink)}
  .btn.om:hover{filter:brightness(1.06);border-color:var(--om)}
  .omlogo{display:inline-block;width:1.15em;height:1.15em;flex:none;background:currentColor;
    -webkit-mask:url(data:image/png;base64,) center/contain no-repeat;mask:url(data:image/png;base64,) center/contain no-repeat}
  section.block{padding:6rem 0}
  h2{font-family:var(--display);font-weight:600;font-size:clamp(2.2rem,5vw,3.4rem);letter-spacing:-.03em;line-height:1;margin:0 0 2rem}

  ol.tl{list-style:none;margin:0;padding:0;border-left:1.5px solid var(--line)}
  ol.tl li{display:grid;grid-template-columns:6.6rem 1fr;gap:1rem;position:relative;padding:1.4rem 0 1.4rem 1.6rem;transition:opacity .4s;opacity:.55}
  ol.tl li::before{content:"";position:absolute;left:-6px;top:1.95rem;width:10px;height:10px;border-radius:50%;background:var(--bg);border:1.5px solid var(--muted);transition:background .3s,border-color .3s,transform .3s}
  ol.tl li.on{opacity:1}
  ol.tl li.on::before{background:var(--teal);border-color:var(--teal);transform:scale(1.35)}
  .yr{font-family:var(--display);font-weight:600;font-size:1.25rem;line-height:1.3;color:var(--teal);letter-spacing:-.01em}
  .tt{font-weight:600;line-height:1.35;margin:0 0 .25rem}
  .pl{margin:0;color:var(--muted);font-size:.97rem;line-height:1.45}

  .vbox{max-width:62rem}
  .vgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,17rem),1fr));gap:1.4rem;max-width:62rem}
  .vcard{display:block;text-decoration:none;background:var(--card);border:1px solid var(--line);border-radius:18px;overflow:hidden;transition:transform .25s,border-color .25s}
  .vcard:hover{transform:translateY(-3px);border-color:var(--om)}
  .poster{position:relative;aspect-ratio:16/9;background:linear-gradient(140deg,var(--bg2),var(--bg));overflow:hidden}
  .poster .ring{position:absolute;right:-12%;top:-30%;width:70%;aspect-ratio:1;border-radius:50%;border:10px solid var(--om);opacity:.22}
  .poster .play{position:absolute;left:1rem;bottom:1rem;width:3rem;height:3rem;border-radius:50%;background:var(--om);color:var(--om-ink);display:grid;place-items:center}
  .poster .play svg{width:1.1rem;height:1.1rem;margin-left:.15rem}
  .poster .dur{position:absolute;right:.8rem;bottom:.8rem;font-size:.8rem;font-weight:600;padding:.2rem .5rem;border-radius:6px;background:var(--panel)}
  .vbody{padding:1rem 1.15rem 1.2rem}
  .vbody h3{font-family:var(--display);font-weight:600;font-size:1.15rem;letter-spacing:-.01em;line-height:1.25;margin:0 0 .35rem}
  .vbody p{margin:0;font-size:.92rem;color:var(--muted);line-height:1.45}

  .connect{padding:6rem 0 5rem}
  .joinbox{max-width:46rem;padding:clamp(1.6rem,4vw,3rem);border-radius:28px;color:var(--om-ink);position:relative;overflow:hidden;
    background:var(--om);background:color-mix(in srgb, var(--om) 84%, transparent);
    -webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}
  .joinbox::after{content:"";position:absolute;right:-6rem;bottom:-7rem;width:18rem;height:18rem;border-radius:50%;border:2.2rem solid currentColor;opacity:.08}
  .joinbox .om{display:flex;align-items:center;gap:.5rem;font-family:var(--display);font-weight:600;font-size:1.05rem;margin:0 0 1.4rem}
  .joinbox .om .omlogo{width:1.6rem;height:1.6rem}
  .joinbox h3{font-family:var(--display);font-weight:800;font-size:clamp(1.9rem,4vw,2.7rem);letter-spacing:-.035em;line-height:1;margin:0;max-width:16ch}
  .joinbox p{max-width:30rem;margin:1rem 0 1.8rem}
  .joinbox .btn{border-color:currentColor;color:var(--om-ink)}
  .joinbox .btn.solid{background:var(--om-ink);color:var(--om);border-color:var(--om-ink)}
  .joinbox .btn:hover{border-color:currentColor}
  footer{padding:2rem 0 3rem;color:var(--muted);font-size:.85rem;border-top:1px solid var(--line)}

  /* ---------- Demo picker ---------- */
  .picker{
    position:fixed;z-index:20;top:50%;right:calc(1rem + env(safe-area-inset-right,0px));transform:translateY(-50%);
    width:14rem;background:var(--panel);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);
    border:1px solid var(--line);border-radius:20px;box-shadow:0 18px 50px -20px rgba(0,0,0,.35);color:var(--ink);
  }
  .pk-toggle{all:unset;box-sizing:border-box;cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:.6rem;width:100%;
    padding:.9rem 1rem;font:600 .95rem/1.2 var(--body);border-radius:20px}
  .pk-toggle svg{width:1rem;height:1rem;transition:transform .25s}
  .picker[data-open="false"] .pk-toggle svg{transform:rotate(180deg)}
  .picker[data-open="false"] .pk-body{display:none}
  .pk-body{padding:0 1rem 1rem}
  .pk-h{margin:.2rem 0 .6rem;font-size:.75rem;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
  .swatches{display:flex;gap:.5rem;flex-wrap:wrap}
  .sw{all:unset;cursor:pointer;width:1.9rem;height:1.9rem;border-radius:50%;box-shadow:inset 0 0 0 1px rgba(0,0,0,.12);position:relative;transition:transform .15s}
  .sw:hover{transform:scale(1.08)}
  .sw[aria-checked="true"]{box-shadow:0 0 0 2px var(--panel),0 0 0 4px var(--ink)}
  .sw:focus-visible{outline:2px solid var(--ink);outline-offset:4px}
  .pk-name{margin:.55rem 0 1.1rem;font-size:.88rem;color:var(--muted)}
  .models{display:flex;flex-direction:column;gap:.3rem}
  .md{all:unset;box-sizing:border-box;cursor:pointer;padding:.55rem .8rem;border-radius:10px;font:500 .93rem/1.2 var(--body);border:1px solid transparent;transition:background .2s}
  .md:hover{background:color-mix(in srgb, var(--ink) 7%, transparent)}
  .md[aria-checked="true"]{background:var(--teal);color:var(--teal-ink);font-weight:600}
  .md:focus-visible{outline:2px solid var(--ink);outline-offset:2px}

  @media (max-width:820px){
    #scene{opacity:.42}
    .panel{background:var(--panel);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);border-radius:20px;padding:1.4rem}
    section.block{padding:3.5rem 0}
    ol.tl li{grid-template-columns:1fr;gap:.2rem}
    .vgrid{gap:1rem}
    .picker{top:auto;transform:none;left:0;right:0;bottom:0;width:auto;border-radius:20px 20px 0 0;border-bottom:none;
      padding-bottom:env(safe-area-inset-bottom,0px)}
    .pk-toggle{padding:1rem 1.25rem}
    .pk-body{padding:0 1.25rem 1rem}
    .models{flex-direction:row;flex-wrap:wrap}
    footer{padding-bottom:6rem}
  }
  .fade{opacity:0;transform:translateY(14px);transition:opacity .9s ease,transform .9s ease}
  .ready .fade{opacity:1;transform:none}
  .ready .fade.d2{transition-delay:.25s}.ready .fade.d3{transition-delay:.45s}.ready .fade.d4{transition-delay:.65s}
  @media (prefers-reduced-motion: reduce){
    html{scroll-behavior:auto}
    .hint::before{animation:none}
    .btn,.vcard,ol.tl li,ol.tl li::before,.sw,.md,body{transition:none}
    .fade{opacity:1;transform:none;transition:none}
  }
</style>
</head>
<body>
<canvas id="scene" aria-hidden="true"></canvas>

<aside class="picker" id="picker" data-open="true" aria-label="Personnaliser la page">
  <button class="pk-toggle" id="pkToggle" aria-expanded="true" aria-controls="pkBody">
    Personnaliser
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 15l6-6 6 6"/></svg>
  </button>
  <div class="pk-body" id="pkBody">
    <p class="pk-h" id="lblColor">Couleur principale</p>
    <div class="swatches" id="swatches" role="radiogroup" aria-labelledby="lblColor"></div>
    <p class="pk-name" id="palName"></p>
    <p class="pk-h" id="lblModel">Modèle 3D</p>
    <div class="models" id="models" role="radiogroup" aria-labelledby="lblModel"></div>
  </div>
</aside>

<main id="top">
  <div class="wrap">
    <section class="hero">
      <div class="col">
        <div class="avatar fade" aria-hidden="true">
          <svg viewBox="0 0 100 100" fill="currentColor"><circle cx="50" cy="38" r="19"/><path d="M12 100c0-22 17-37 38-37s38 15 38 37z"/></svg>
        </div>
        <p class="partner fade">Médecin partenaire <b>OrthoMaster</b></p>
        <h1 class="fade d2"><span class="dr">Docteur</span><span class="ln">Prénom</span><span class="ln">Nom</span></h1>
        <p class="role creds fade d3">MB BS, PM&amp;R SAS, MSc Sports Performance, CSL, PhD</p>
        <ul class="expertise fade d3" aria-label="Domaines d’expertise">
          <li>Rééducation orthopédique</li>
          <li>Médecine du sport</li>
          <li>Médecine régénérative</li>
          <li>Échographie musculo-squelettique</li>
        </ul>
        <p class="lede fade d3">Quelques mots sur votre pratique et votre approche du soin.</p>
        <div class="actions fade d4">
          <a class="btn" href="#"><img class="ico" src="data:image/png;base64," alt="" width="18" height="18">Doctolib</a>
          <a class="btn" href="#"><svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><rect width="24" height="24" rx="6" fill="#0A66C2"/><path fill="#fff" transform="translate(12 12) scale(.6) translate(-12 -11.75)" d="M6.9 8.8H3.6V20h3.3V8.8zM5.2 3.5a1.9 1.9 0 1 0 0 3.8 1.9 1.9 0 0 0 0-3.8zM20.4 13.6c0-3-1.6-5-4.3-5-1.4 0-2.4.8-2.8 1.5V8.8H10V20h3.3v-5.6c0-1.5.4-2.9 2.2-2.9 1.8 0 1.8 1.7 1.8 3V20h3.3l-.2-6.4z"/></svg>LinkedIn</a>
          <a class="btn om" href="#"><span class="omlogo" aria-hidden="true"></span>OrthoMaster</a>
        </div>
        <p class="hint fade d4">Faites défiler pour découvrir le parcours</p>
      </div>
    </section>

    <section class="block" id="formation">
      <div class="col panel">
        <h2>Formation</h2>
        <ol class="tl">
          <li data-disc="8"><div class="yr">2018</div><div><p class="tt">Diplôme universitaire de votre spécialité</p><p class="pl">Faculté de médecine, Ville</p></div></li>
          <li data-disc="7"><div class="yr">2015</div><div><p class="tt">Diplôme d’études spécialisées</p><p class="pl">Université, Ville</p></div></li>
          <li data-disc="6"><div class="yr">2013</div><div><p class="tt">Master en sciences biomédicales</p><p class="pl">Faculté de médecine, Ville</p></div></li>
          <li data-disc="5"><div class="yr">2011</div><div><p class="tt">Doctorat en médecine</p><p class="pl">Faculté de médecine, Ville</p></div></li>
        </ol>
      </div>
    </section>

    <section class="block" id="parcours">
      <div class="col panel">
        <h2>Parcours</h2>
        <ol class="tl">
          <li data-disc="4"><div class="yr">Depuis 2022</div><div><p class="tt">Cabinet libéral</p><p class="pl">Ville</p></div></li>
          <li data-disc="3"><div class="yr">2019–2022</div><div><p class="tt">Praticien hospitalier</p><p class="pl">Centre hospitalier, Ville</p></div></li>
          <li data-disc="2"><div class="yr">2017–2019</div><div><p class="tt">Chef de clinique assistant</p><p class="pl">CHU, Ville</p></div></li>
          <li data-disc="1"><div class="yr">2015–2017</div><div><p class="tt">Assistant spécialiste</p><p class="pl">Centre hospitalier, Ville</p></div></li>
          <li data-disc="0"><div class="yr">2011–2015</div><div><p class="tt">Interne des hôpitaux</p><p class="pl">CHU, Ville</p></div></li>
        </ol>
      </div>
    </section>

    <section class="block videos" id="videos">
      <div class="vbox panel">
        <h2>Ses vidéos avec OrthoMaster</h2>
        <div class="vgrid">
          <a class="vcard" href="#"><div class="poster"><span class="ring"></span><span class="play"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M7 4.5v15l12-7.5z"/></svg></span><span class="dur">4:12</span></div><div class="vbody"><h3>Titre de la vidéo 1</h3><p>Courte description du sujet abordé.</p></div></a>
          <a class="vcard" href="#"><div class="poster"><span class="ring"></span><span class="play"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M7 4.5v15l12-7.5z"/></svg></span><span class="dur">6:30</span></div><div class="vbody"><h3>Titre de la vidéo 2</h3><p>Courte description du sujet abordé.</p></div></a>
          <a class="vcard" href="#"><div class="poster"><span class="ring"></span><span class="play"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M7 4.5v15l12-7.5z"/></svg></span><span class="dur">3:45</span></div><div class="vbody"><h3>Titre de la vidéo 3</h3><p>Courte description du sujet abordé.</p></div></a>
        </div>
      </div>
    </section>

    <section class="connect" id="contact">
      <div class="joinbox">
        <p class="om"><span class="omlogo" aria-hidden="true"></span>OrthoMaster</p>
        <h3>Toutes ses vidéos, et celles d’autres spécialistes</h3>
        <p>OrthoMaster est la plateforme de l’orthopédie pour les professionnels de santé. Créez votre compte pour accéder à l’ensemble des vidéos de ce médecin et des autres médecins partenaires.</p>
        <div class="actions">
          <a class="btn solid" href="https://auth.orthomaster.fr/register" target="_blank" rel="noopener">Rejoindre OrthoMaster</a>
          <a class="btn" href="#">Découvrir la plateforme</a>
        </div>
      </div>
    </section>

    <footer>Page partenaire OrthoMaster.</footer>
  </div>
</main>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
(function(){
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  requestAnimationFrame(()=>document.body.classList.add('ready'));
  const root = document.documentElement;

  // ================= Timeline state =================
  let active = -1, allLit = false;
  const items = [...document.querySelectorAll('ol.tl li')];
  const io = new IntersectionObserver(entries=>{
    entries.forEach(e=>{ if(e.isIntersecting){ items.forEach(i=>i.classList.remove('on')); e.target.classList.add('on'); active = +e.target.dataset.disc; } });
  },{rootMargin:'-42% 0px -42% 0px'});
  items.forEach(i=>io.observe(i));
  const vids = document.getElementById('videos');
  addEventListener('scroll',()=>{
    if(scrollY < innerHeight*0.5){ active=-1; items.forEach(i=>i.classList.remove('on')); }
    allLit = vids.getBoundingClientRect().top < innerHeight*0.55;
  },{passive:true});

  // ================= Palettes =================
  // Primary colour = the doctor's colour (accents, timeline, 3D glow).
  // OrthoMaster brand (#FF9600) never changes: partner dot, OrthoMaster button, videos, join block, 3D "OrthoMaster" phase.
  const PALETTES = [
    { name:'Turquoise', swatch:'#1f8379',
      light:{bg:'#e3ebf0',bg2:'#cfdde7',ink:'#13293d',muted:'#4d6578',teal:'#1f8379','teal-ink':'#ffffff',line:'rgba(19,41,61,.16)',panel:'rgba(227,235,240,.82)',card:'#f3f7f9'},
      dark:{bg:'#10283a',bg2:'#1a3d57',ink:'#ece7dc',muted:'#9db2c3',teal:'#4cbcb0','teal-ink':'#0d2231',line:'rgba(236,231,220,.15)',panel:'rgba(16,40,58,.78)',card:'#16344b'} },
    { name:'Orange OrthoMaster', swatch:'#FF9600',
      light:{bg:'#f3ece4',bg2:'#ead9c6',ink:'#2a1c10',muted:'#6b5848',teal:'#b35f00','teal-ink':'#ffffff',line:'rgba(42,28,16,.15)',panel:'rgba(243,236,228,.84)',card:'#fbf7f2'},
      dark:{bg:'#221810',bg2:'#3d2a19',ink:'#f3eadf',muted:'#c2ab95',teal:'#ffa733','teal-ink':'#221810',line:'rgba(243,234,223,.15)',panel:'rgba(34,24,16,.78)',card:'#2e2116'} },
    { name:'Bleu océan', swatch:'#2563EB',
