    legs:{ meta:{"q":3.8002076148986816,"nv":75564,"ni":452736,"bones":[[0,502,0,3000,0],[502,592,3000,3540,0],[1094,676,6540,4044,0],[1770,1490,10584,8928,0],[3260,649,19512,3882,0],[3909,1263,23394,7566,0],[5172,590,30960,3528,0],[5762,712,34488,4260,0],[6474,599,38748,3582,0],[7073,673,42330,4026,0],[7746,642,46356,3840,0],[8388,621,50196,3714,0],[9009,1391,53910,8334,0],[10400,682,62244,4080,0],[11082,1434,66324,8592,0],[12516,666,74916,3984,0],[13182,1263,78900,7566,1],[14445,1299,86466,7782,1],[15744,592,94248,3540,0],[16336,610,97788,3648,0],[16946,815,101436,4878,0],[17761,707,106314,4230,0],[18468,1400,110544,8388,1],[19868,1315,118932,7878,1],[21183,986,126810,5904,2],[22169,977,132714,5850,2],[23146,1123,138564,6726,1],[24269,1222,145290,7320,1],[25491,914,152610,5472,1],[26405,880,158082,5268,1],[27285,1096,163350,6564,1],[28381,1713,169914,10266,3],[30094,1137,180180,6810,1],[31231,1785,186990,10698,3],[33016,925,197688,5538,2],[33941,1161,203226,6954,2],[35102,1254,210180,7512,2],[36356,1107,217692,6630,2],[37463,1441,224322,8634,2],[38904,1398,232956,8376,2],[40302,642,241332,3840,2],[40944,626,245172,3744,2],[41570,1202,248916,7200,3],[42772,1260,256116,7548,3],[44032,2263,263664,13566,4],[46295,2173,277230,13026,4],[48468,3345,290256,20058,5],[51813,3217,310314,19290,5],[55030,892,329604,5340,6],[55922,910,334944,5448,6],[56832,3851,340392,23094,7],[60683,3973,363486,23826,7],[64656,4398,387312,26376,8],[69054,4439,413688,26634,8],[73493,2071,440322,12414,8]],"bandY":[-3.722,-3.629,-3.519,-3.493,-1.837,-1.607,-0.062,1.364,3.019]}, b64:"" }
  };
  const rawCache = {};
  const decode = k => rawCache[k] || (rawCache[k] = Uint8Array.from(atob(DATA[k].b64), c=>c.charCodeAt(0)).buffer);
  function partGeo(posQ, idxAll, q, vo, nv, io, ni){
    const pos = new Float32Array(nv*3), s = q/32767;
    for(let k=0;k<nv*3;k++) pos[k] = posQ[vo*3+k]*s;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos,3));
    geo.setIndex(new THREE.BufferAttribute(idxAll.slice(io, io+ni),1));
    geo.computeVertexNormals(); return geo;
  }
  const ease = t=>1-Math.pow(1-Math.min(Math.max(t,0),1),3);

  // Spine: BodyParts3D vertebrae + measured intervertebral discs (23 discs -> 9 groups)
  function buildSpine(){
    const M = DATA.spine.meta, raw = decode('spine');
    const posQ = new Int16Array(raw,0,M.nv*3), idxAll = new Uint16Array(raw,M.nv*6,M.ni);
    const g0 = new THREE.Group(), segs = [], discs = [];
    const boneMat = new THREE.MeshStandardMaterial({color:BONE, roughness:.52, metalness:.04});
    M.parts.forEach(([vo,nv,io,ni],i)=>{
      const g = new THREE.Group(); g.add(new THREE.Mesh(partGeo(posQ,idxAll,M.q,vo,nv,io,ni), boneMat));
      g.userData = { delay:i*.055 }; g0.add(g); segs.push(g);
    });
    const ND = M.discs.length, bandY = Array(9).fill(0), bandN = Array(9).fill(0);
    M.discs.forEach((dd,j)=>{
      const sh = new THREE.Shape(), p = dd.pts;
      for(let i=0;i<p.length;i+=2) i===0 ? sh.moveTo(p[i],p[i+1]) : sh.lineTo(p[i],p[i+1]);
      const bev = dd.h*.28, depth = Math.max(.002, dd.h-2*bev);
      const geo = new THREE.ExtrudeGeometry(sh,{depth, bevelEnabled:true, bevelThickness:bev, bevelSize:bev*.35, bevelSegments:3, curveSegments:4});
      geo.translate(0,0,-depth/2); geo.computeVertexNormals();
      const m = new THREE.MeshStandardMaterial({color:teal.clone(), emissive:teal.clone(), emissiveIntensity:.12, roughness:.35, transparent:true, opacity:.94});
      const d = new THREE.Mesh(geo,m);
      d.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(new THREE.Vector3(...dd.u), new THREE.Vector3(...dd.w), new THREE.Vector3(...dd.d)));
      const grp = Math.min(8, Math.floor(j*9/ND)); bandY[grp]+=dd.c[1]; bandN[grp]++;
      d.userData = { x:dd.c[0], y:dd.c[1], z:dd.c[2], grp, glow:.12, delay:j*.055+.08 };
      g0.add(d); discs.push(d);
    });
    for(let g=0; g<9; g++) bandY[g] /= Math.max(1,bandN[g]);
    return { root:g0, look:i=>bandY[i]*.35, update(tl,t){
      segs.forEach(g=>{ const k = reduce?1:ease((tl-.3-g.userData.delay)/1.1);
        g.position.set(0,(1-k)*4,0); g.rotation.y=(1-k)*1.2; g.scale.setScalar(.001+k*.999); });
      discs.forEach((d,i)=>{
        const du=d.userData, k = reduce?1:ease((tl-.5-du.delay)/1.1);
        d.position.set(du.x, du.y+(1-k)*4, du.z);
        let target = du.grp===active ? 1.35 : (active>=0 && du.grp>active ? .45 : .12);
        if(allLit) target = .55 + .25*Math.sin(t*2 - i*.35);
        du.glow += (target-du.glow)*.08;
        d.material.emissiveIntensity = du.glow;
        d.material.color.copy(teal).lerp(OM_SHADES[i%9],omK);
        d.material.emissive.copy(teal).lerp(OM_EMIS[i%9],omK);
        const f = (.001+k*.999)*(1+(du.glow-.12)*.04);
        d.scale.set(f, f, .001+k*.999);
      });
    }};
  }

  // Knee / hand: one fused mesh, glow painted by height (shader band) + CT-style reveal
  function buildBand(key){
    const M = DATA[key].meta, raw = decode(key);
    const geo = partGeo(new Int16Array(raw,0,M.nv*3), new Uint16Array(raw,M.nv*6,M.ni), M.q, 0, M.nv, 0, M.ni);
    const U = { uBandY:{value:M.yMax}, uBandW:{value:.42}, uBand:{value:0}, uPassed:{value:0}, uOm:{value:0},
      uTime:{value:0}, uReveal:{value:reduce?99:M.yMin-.2}, uTeal:{value:teal}, uOrange:{value:om} };
    const mat = new THREE.MeshStandardMaterial({color:BONE.clone(), roughness:.5, metalness:.04, side:THREE.DoubleSide});
    mat.onBeforeCompile = sh=>{
      Object.assign(sh.uniforms, U);
      sh.vertexShader = 'varying float vY;\n' + sh.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n  vY = position.y;');
      sh.fragmentShader = 'varying float vY;\nuniform float uBandY,uBandW,uBand,uPassed,uOm,uTime,uReveal;\nuniform vec3 uTeal,uOrange;\nfloat kBand,kPassed,kWave,kEdge;\n' +
        sh.fragmentShader
        .replace('#include <color_fragment>', `#include <color_fragment>
  if(vY > uReveal) discard;
  kEdge = smoothstep(.14, 0., uReveal - vY);
  kBand = exp(-pow((vY-uBandY)/uBandW, 2.)) * uBand;
  kPassed = smoothstep(uBandY + uBandW*.4, uBandY + uBandW*1.6, vY) * uPassed;
  kWave = .5 + .5*sin(vY*2.6 - uTime*2.);
  vec3 tealTint = mix(diffuseColor.rgb, uTeal, clamp(kBand*.92 + kPassed*.38, 0., 1.));
  vec3 omTint = mix(diffuseColor.rgb, uOrange, .45 + .35*kWave);
  diffuseColor.rgb = mix(tealTint, omTint, uOm);`)
        .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
  totalEmissiveRadiance += mix(uTeal*(kBand*.55 + kPassed*.08), uOrange*(.12 + .14*kWave), uOm) + uTeal*kEdge*1.6;`);
    };
    const g0 = new THREE.Group(); g0.add(new THREE.Mesh(geo,mat));
    const span = M.yMax-M.yMin, bandY = [...Array(9)].map((_,g)=> M.yMin + span*(.07+.86*g/8));
    return { root:g0, look:i=>bandY[i]*.35, update(tl,t,hasBand){
      U.uTime.value = t;
      if(!reduce) U.uReveal.value = M.yMin-.2 + Math.max(0,(tl-.3)/2.4)*(span+.6);
      if(hasBand) U.uBandY.value += (bandY[active]-U.uBandY.value)*.08;
      U.uBand.value += ((hasBand?1:0)-U.uBand.value)*.06;
      U.uPassed.value = U.uBand.value;
      U.uOm.value = omK;
    }};
  }

  // Foot / lower limbs: separate bones, each with its own group (0..8)
  function buildBones(key, opt){
    const M = DATA[key].meta, raw = decode(key);
    const posQ = new Int16Array(raw,0,M.nv*3), idxAll = new Uint16Array(raw,M.nv*6,M.ni);
    const g0 = new THREE.Group(), inner = new THREE.Group(); inner.scale.setScalar(opt.scale||1); g0.add(inner);
    const bones = [], c1 = new THREE.Color(), c2 = new THREE.Color();
    M.bones.forEach(([vo,nv,io,ni,grp],i)=>{
      const mat = new THREE.MeshStandardMaterial({color:BONE.clone(), emissive:new THREE.Color(0), roughness:.5, metalness:.04});
      const m = new THREE.Mesh(partGeo(posQ,idxAll,M.q,vo,nv,io,ni), mat);
      m.userData = { g: opt.rev ? 8-grp : grp, glow:0, tint:0, delay:i*opt.stagger };
      inner.add(m); bones.push(m);
    });
    return { root:g0, look:i=> (opt.look && M.bandY) ? M.bandY[opt.rev?8-i:i]*opt.look : 0, update(tl,t){
      const on = !allLit && active>=0;
      bones.forEach((m,i)=>{
        const u = m.userData, k = reduce?1:ease((tl-.3-u.delay)/1.0);
        m.position.set(0,(1-k)*3,0); m.scale.setScalar(.001+k*.999);
        const tT = on ? (u.g===active ? .85 : (u.g>active ? .3 : 0)) : 0, tG = on && u.g===active ? .5 : 0;
        u.tint += (tT-u.tint)*.08; u.glow += (tG-u.glow)*.08;
        const wave = .5+.5*Math.sin(t*2 - i*.45), shade = OM_SHADES[i%9];
        m.material.color.copy(BONE).lerp(teal,u.tint).lerp(c1.copy(BONE).lerp(shade,.45+.35*wave), omK);
        m.material.emissive.copy(teal).multiplyScalar(u.glow).lerp(c2.copy(shade).multiplyScalar(.12+.12*wave), omK);
      });
    }};
  }

  const MODELS = {
    spine:{ build:buildSpine, base:1.15, s:[1,.82], lean:[0,0,-.06], px:.7 },
    knee: { build:()=>buildBand('knee'), base:.55, s:[1,.85], lean:[0,0,0], px:.7 },
    hand: { build:()=>buildBand('hand'), base:.55, s:[1,.85], lean:[0,0,0], px:.7 },
    foot: { build:()=>buildBones('foot',{rev:true, stagger:.07, scale:1.05, look:0}), base:.9, s:[1,.85], lean:[.38,0,-.16], px:.72 },
    legs: { build:()=>buildBones('legs',{rev:false, stagger:.03, scale:1, look:.2}), base:.9, s:[.92,.82], lean:[0,0,0], px:.7 }
  };

  const lean = new THREE.Group(); scene.add(lean);
  const spin = new THREE.Group(); lean.add(spin);
  const P=320, ppos=new Float32Array(P*3), spd=new Float32Array(P);
  for(let i=0;i<P;i++){ const a=Math.random()*Math.PI*2, r=1.4+Math.random()*2.6; ppos[i*3]=Math.cos(a)*r; ppos[i*3+1]=(Math.random()-.5)*11; ppos[i*3+2]=Math.sin(a)*r; spd[i]=.15+Math.random()*.35; }
  const pGeo=new THREE.BufferGeometry(); pGeo.setAttribute('position',new THREE.BufferAttribute(ppos,3));
  const pMat=new THREE.PointsMaterial({color:teal.clone(), size:.045, transparent:true, opacity:.55, depthWrite:false});
  const dust = new THREE.Points(pGeo,pMat); scene.add(dust);

  const clock = new THREE.Clock();
  let cur = null, def = null, t0 = 0;
  function disposeTree(o){ o.traverse(n=>{ if(n.geometry) n.geometry.dispose(); if(n.material) n.material.dispose(); }); }
  function setModel(k){
    if(cur){ spin.remove(cur.root); disposeTree(cur.root); }
    def = MODELS[k]; cur = def.build(); spin.add(cur.root);
    lean.rotation.set(...def.lean); t0 = clock.getElapsedTime(); resize();
  }

  let mobile=false, deskX=2.7;
  function resize(){
    const w=innerWidth,h=innerHeight; renderer.setSize(w,h,false); camera.aspect=w/h; camera.updateProjectionMatrix(); mobile = w<820;
    const frameW = Math.min(w,1280), frameLeft = (w-frameW)/2;
    const px = frameLeft + frameW*((def&&def.px)||.7);
    const visW = 2*15*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*camera.aspect;
    deskX = ((px/w)-.5)*visW/.65;
  }
  addEventListener('resize',resize);
  setModel(state.model);
  onModel = setModel;

  let mx=0,my=0,tx=0,ty=0;
  addEventListener('pointermove',e=>{ tx=(e.clientX/innerWidth-.5)*2; ty=(e.clientY/innerHeight-.5)*2; },{passive:true});
  let lookY=0, spinX=deskX;

  function frame(){
    const t = clock.getElapsedTime(), tl = t - t0;
    mx += (tx-mx)*.05; my += (ty-my)*.05;
    const maxScroll = Math.max(1, document.documentElement.scrollHeight - innerHeight);
    const sp = scrollY/maxScroll;
    omK += ((allLit?1:0)-omK)*.05; mix.copy(teal).lerp(om,omK);
    const hasBand = !allLit && active>=0;
    cur.update(tl, t, hasBand);

    const arr=pGeo.attributes.position.array;
    if(!reduce){ for(let i=0;i<P;i++){ arr[i*3+1]+=spd[i]*.006; if(arr[i*3+1]>5.5) arr[i*3+1]=-5.5; } pGeo.attributes.position.needsUpdate=true; }
    pMat.color.copy(mix); rim.color.copy(mix);

    const targetX = mobile ? 0 : deskX;
    spinX += (targetX-spinX)*.08;
    lean.position.x = spinX; dust.position.x = spinX;
    dust.rotation.y = spin.rotation.y;
    spin.scale.setScalar(mobile ? def.s[1] : def.s[0]);
    spin.rotation.y = (reduce?0:t*.12) + sp*Math.PI*1.4 + mx*.45 + def.base;
    spin.rotation.x = my*.12;

    const ay = hasBand ? cur.look(active) : 0;
    lookY += (ay-lookY)*.05;
    camera.position.y = lookY; camera.lookAt(spinX*.35, lookY, 0);

    renderer.render(scene,camera);
    requestAnimationFrame(frame);
  }
  frame();
})();
</script>
</body>
</html>